Pin Kotlin by specifying its version in the Gradle `plugins` block.

```kotlin
// build.gradle.kts
plugins {
    kotlin("jvm") version "2.0.21"
}
```

For a multi-module project, declare it once in the root project:

```kotlin
// root build.gradle.kts
plugins {
    kotlin("jvm") version "2.0.21" apply false
}

// module build.gradle.kts
plugins {
    kotlin("jvm")
}
```

You can also use a version catalog:

```toml
# gradle/libs.versions.toml
[versions]
kotlin = "2.0.21"

[plugins]
kotlin-jvm = { id = "org.jetbrains.kotlin.jvm", version.ref = "kotlin" }
```

Then apply `alias(libs.plugins.kotlin.jvm)` in your module.
